import json
# Parse each line, track parent vs subagent by looking at message.role and message.parent_tool_use_id
for path, label in [("evidence/run-inline.jsonl","INLINE"),("evidence/run-sub.jsonl","SUB")]:
  print(f"\n===== {label} =====")
  parent_tools=[]
  sub_tools=[]
  agent_return_tokens = 0
  for line in open(path):
    d=json.loads(line)
    if d.get("type") not in ("assistant","user","result"): continue
    msg=d.get("message") or {}
    parent_id = d.get("parent_tool_use_id")
    for c in msg.get("content") or []:
      if not isinstance(c, dict): continue
      if c.get("type")=="tool_use":
        inp=c["input"] or {}
        key=inp.get("file_path") or inp.get("pattern") or inp.get("command") or inp.get("subagent_type") or str(inp.get("description",""))[:40]
        entry=(c["name"], str(key)[-60:])
        if parent_id: sub_tools.append(entry)
        else: parent_tools.append(entry)
      elif c.get("type")=="tool_result":
        # Look for Agent tool result — count tokens returned
        content = c.get("content")
        if isinstance(content, list):
          for tc in content:
            if isinstance(tc,dict) and tc.get("type")=="text":
              t=tc.get("text","")
              if "COMMON_MISCONCEPTIONS" in t or "SEVERITY_BY_CRITERION" in t:
                print(f"[SUBAGENT RETURN {len(t)} chars]:")
                print(t[:1000])
    if d.get("type")=="result":
      print(f"num_turns: {d.get('num_turns')}  duration_ms: {d.get('duration_ms')}  cost: {d.get('total_cost_usd')}")
      u=d.get("usage") or {}
      print(f"usage: {u}")
  print(f"\nPARENT tools ({len(parent_tools)}):")
  for t in parent_tools: print("  ", t)
  print(f"SUB tools ({len(sub_tools)}):")
  for t in sub_tools: print("  ", t)
